    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xEBB2702FA331BBE3ULL + 0xFAE94ABC131602CEULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xB438211E5C9D76DFULL + 0x93B42AFB7642C204ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseB(pNonce * 0x89955F84B9B0095FULL + 0xCAA8B76FCC4A7102ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseA(pNonce * 0xDC1D29782AF0DE99ULL + 0xF2EC9C97D91AC3C2ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseB(pNonce * 0x99E5BE6D3F5ADFADULL + 0xC1F0C69C872138AFULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseB(pNonce * 0x878055B0513B4E19ULL + 0xE25C04545972D8B5ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseA(pNonce * 0xF210CA2BABE2BB8BULL + 0xA46A0934D6B12E81ULL);
