    [[maybe_unused]] const std::uint64_t aNonceWordI = TwistMix64::DiffuseA(pNonce * 0xDD2FD7E37B7688EBULL + 0xEBF56F3268A8F78AULL);
    [[maybe_unused]] const std::uint64_t aNonceWordJ = TwistMix64::DiffuseA(pNonce * 0xC8D56898F621A843ULL + 0x809F7F32973EBAA9ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordK = TwistMix64::DiffuseB(pNonce * 0x843D39CAFB8CAC97ULL + 0xE56E5A43F4A0A659ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordL = TwistMix64::DiffuseA(pNonce * 0xC66F28CA142AA481ULL + 0xB1FCEA8C9D999389ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordM = TwistMix64::DiffuseC(pNonce * 0xC96E6BF83E885AF1ULL + 0x8A3E2CB87BE71A60ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordN = TwistMix64::DiffuseC(pNonce * 0x956A0C86920DD243ULL + 0xEF247655222E142EULL);
    [[maybe_unused]] const std::uint64_t aNonceWordO = TwistMix64::DiffuseA(pNonce * 0xD0C831EC4DB07D99ULL + 0xAFAEB6EE80F95029ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordP = TwistMix64::DiffuseB(pNonce * 0x94B2337515BCFF55ULL + 0xB57FDC4D4803A6B1ULL);
