        //
        // Ingress:
        //      aMagmaLaneD (-->), aMagmaLaneB (-->), aSpiritLaneB (<-?->)
        //
        // Cross:
        //      aMagmaLaneC (<--), aMagmaLaneA (<--), aSpiritLaneA (<-?->)
        //
